-- EVT lua patch for chronicle_mode_top_menu (common/script/lua/menu/chronicle_mode_top_menu_6.00.06.00.lua.bin). Graft training_ground. Generated by research/scripts/menu_assemble.py (build --out patches) from research/grafts/; do not edit by hand.
-- ===== EVT training ground start BEGIN =====
-- Training Ground (graft.toml; docs/game/mods/training-ground.md), every hub of the menus that shows the top bar:
-- «Match» › «Free Mode» starts the drill RIGHT HERE, with the framework's match start service (VRFW_MATCH,
-- lua\_all\12_match_start.lua): the plan of scripts\training_ground.lua (CMND_TRAININGGROUND_PLAN: row, class, stadium,
-- next-match overrides), play mode Competición (the mode's VS team), the friendly training_ground (return = "menus")
-- reserved from this menu. The retail match intro shows (the friendly's encounter transition over this hub, the 5v5 VS
-- screen, the walk-in); a restart («Aplicar cambios», «Reiniciar») stays black from the hub's first frame. A 5v5 drill
-- whose VS team has no complete 5v5 line-up (the retail member check) plays with the active pachanga team (friendly
-- training_ground_pachanga). After the match the soccer state reopens THIS hub with the game kept; the framework
-- closes the friendly and puts the hub's play mode back (and the VS team, after a pachanga team); after a restart this
-- file starts the drill again.
--   * VRFW_TopBarHere["training_ground.start"]: the top bar serves the entry here (else: its title path);
--   * TrainingGround_Launch.start(): the launch (also the title fallback's step in soccer_top_menu,
--     training_ground_hub.lua, and TrainingGround_Start, the mode type's start).
-- Wrappers only (OnInit); engine calls only from them / the top bar's go. Nothing at chunk load.
TrainingGround_Launch = TrainingGround_Launch or {}
do
  local S = TrainingGround_Launch
  S.ENTRY = "training_ground.start"
  S.C = {
    LOG = 3661580131, PLAN = 1738185338, STATE = 102999889,
    LEAVE = 1040250234, GET_VS_SET = 3713813716 --[[CMND_GET_VS_USE_TEAM_SET]],
    SE = 1917805374, SE_NO = 2086672038,
    MEMBER_CHECK = 1538643580, -- retail member check of a team set's line-up (set, kind 1 = 5v5, false) -> 1..10 = incomplete
  }
  S.RELAUNCH_SETTLE = 20 -- frames after the hub opened (its own init and the friendly's close first)

  function S.log(...)
    pcall(funcLuaCommand, S.C.LOG, "EVT training_ground start", ...)
  end

  -- the 5v5 line-up of a team set is complete (the retail rule of «Establecer como equipo activo» in Pachanga)
  local function complete5(set)
    if type(set) ~= "number" or set < 0 then return false end
    local ok, code = pcall(funcLuaCommand, S.C.MEMBER_CHECK, set, 1, false)
    return not (ok and type(code) == "number" and code > 0 and code < 11)
  end

  -- the user's team of the drill, read under the match's play mode: the mode's VS team; a small (5v5) drill whose VS
  -- team has no complete 5v5 line-up takes the active pachanga team (its friendly swaps it in and back)
  local function team_of(plan)
    local vs = funcLuaCommand(S.C.GET_VS_SET)
    if not plan.small or type(plan.friendly_team) ~= "string" or plan.friendly_team == "" or complete5(vs) then
      return vs
    end
    local P = VRFW_PACHANGA
    local ps = (type(P) == "table" and type(P.pachanga_set) == "function") and P.pachanga_set() or nil
    if type(ps) == "number" then
      S.log("the VS team", tostring(vs), "has no complete 5v5 line-up: the active pachanga team", ps)
      return ps, plan.friendly_team
    end
    S.log("the VS team", tostring(vs), "has no complete 5v5 line-up and there is no active pachanga team: its holes",
      "are filled from the bench (rulebook [teams] fill)")
    return vs
  end

  -- the drill from this menu: true = the launch runs, false = refused (nothing changed). `settle` (a restart from the
  -- hub that just opened): black from now on; else the retail intro shows (no forced black)
  function S.start(settle)
    local M = VRFW_MATCH
    if type(M) ~= "table" or type(M.start) ~= "function" then
      S.log("no VRFW_MATCH in this menu")
      return false
    end
    local okp, plan = pcall(funcLuaCommand, S.C.PLAN)
    if not okp or type(plan) ~= "table" or type(plan.game) ~= "number" or plan.game == 0 then
      S.log("no plan: the drill is not started", tostring(plan))
      pcall(funcLuaCommand, S.C.SE, S.C.SE_NO)
      return false
    end
    local ok, why = M.start{
      friendly = plan.friendly, game = plan.game, difficulty = plan.difficulty, stadium = plan.stadium,
      overrides = plan.overrides, play_mode = 1, settle = settle, black = settle ~= nil,
      set = function() return team_of(plan) end,
      on_failed = function(w)
        pcall(funcLuaCommand, S.C.LEAVE, -1)
        S.log("start failed", tostring(w))
      end,
    }
    if not ok then
      pcall(funcLuaCommand, S.C.LEAVE, -1)
      S.log("refused here", tostring(why))
      return false
    end
    S.log("start", tostring(plan.friendly), plan.game, plan.difficulty, plan.stadium)
    return true
  end

  function TrainingGround_Start()
    return S.start()
  end

  -- the top bar's «Free Mode» served in this menu (no title round trip)
  VRFW_TopBarHere = VRFW_TopBarHere or {}
  VRFW_TopBarHere[S.ENTRY] = function(entry, menu)
    S.log("top bar entry served here", tostring(menu))
    return S.start()
  end

  -- back from a drill left with «Reiniciar»: start it again from this hub (the service waits until it settled; black
  -- from the hub's first frame)
  local prev_init = OnInit
  if type(prev_init) == "function" then
    function OnInit(...)
      local r = table.pack(prev_init(...))
      pcall(function()
        local ok, _, again = pcall(funcLuaCommand, S.C.STATE)
        if ok and again == 1 then
          S.log("back from the drill: restart")
          S.start(S.RELAUNCH_SETTLE)
        end
      end)
      return table.unpack(r, 1, r.n)
    end
  end
end
